# Greedy gives 5 but that's an upper bound. Let's check actual chromatic number
# using a proper 4-coloring check with SAT

from pysat.solvers import Solver

def check_k_colorable(edges, n, k):
    """Check if graph is k-colorable using SAT"""
    # Variable x[v][c] = True if vertex v has color c
    # Variable numbering: v*k + c + 1 (1-indexed)

    solver = Solver(name='g3')

    # Each vertex must have at least one color
    for v in range(n):
        clause = [v * k + c + 1 for c in range(k)]
        solver.add_clause(clause)

    # Each vertex has at most one color (at-most-one)
    for v in range(n):
        for c1 in range(k):
            for c2 in range(c1+1, k):
                solver.add_clause([-(v * k + c1 + 1), -(v * k + c2 + 1)])

    # Adjacent vertices have different colors
    for u, v in edges:
        for c in range(k):
            solver.add_clause([-(u * k + c + 1), -(v * k + c + 1)])

    result = solver.solve()
    if result:
        model = solver.get_model()
        colors = [-1] * n
        for v in range(n):
            for c in range(k):
                if (v * k + c + 1) in model:
                    colors[v] = c
        solver.delete()
        return True, colors
    solver.delete()
    return False, None

