from pysat.solvers import Solver

n = 14
edges_circ = [(0, 1), (0, 2), (0, 12), (0, 13), (1, 2), (1, 3), (1, 13), (2, 3), (2, 4), 
              (3, 4), (3, 5), (4, 5), (4, 6), (5, 6), (5, 7), (6, 7), (6, 8), (7, 8), 
              (7, 9), (8, 9), (8, 10), (9, 10), (9, 11), (10, 11), (10, 12), (11, 12), 
              (11, 13), (12, 13)]

def check_k_colorable(edges, n, k):
    solver = Solver(name='g3')
    # Variable: v*k + c + 1 means vertex v has color c
    for v in range(n):
        solver.add_clause([v * k + c + 1 for c in range(k)])
    for v in range(n):
        for c1 in range(k):
            for c2 in range(c1+1, k):
                solver.add_clause([-(v * k + c1 + 1), -(v * k + c2 + 1)])
    for u, v in edges:
        for c in range(k):
            solver.add_clause([-(u * k + c + 1), -(v * k + c + 1)])

    result = solver.solve()
    if result:
        model = solver.get_model()
        model_set = set(model)
        colors = [-1] * n
        for v in range(n):
            for c in range(k):
                if (v * k + c + 1) in model_set:
                    colors[v] = c
        solver.delete()
        return True, colors
    solver.delete()
    return False, None

